const content = {
  en: { locale: "en_US", language: "en-US", title: "Reaction Game", subtitle: "Falling-target reflex training", description: "Free browser reaction game with falling targets. Train visual tracking, interception timing, accuracy, and hand-eye coordination without an account.", keywords: ["reaction game", "reaction time game", "reflex game online", "falling target game", "reaction time trainer", "hand eye coordination game", "visual reaction practice", "free reflex game"], introTitle: "Reaction game and falling-target training guide", intro: ["A reaction game becomes more demanding when the stimulus moves. Instead of waiting for one color change, you detect a target in a lane, estimate where it will be, move the pointer, and click before it escapes. This drill combines visual search, timing, tracking, and motor execution in a short browser session.", "The game records the interval between a target's frame-time appearance and pointer contact using the browser's high-resolution clock. That interval is not a pure nervous-system constant: display refresh, browser scheduling, frame delivery, pointer hardware, visual processing, and hand movement all contribute to the number.", "Falling targets also create a choice problem. You must notice which lane is active, select the useful interception point, and avoid clicking an empty lane. Keeping the cursor relaxed near the upper-middle field lets you respond to new targets without a large panic movement.", "Use the score as a repeatable training signal. Keep display, browser, input device, sensitivity, penalty mode, and session length stable, then compare accuracy, average reaction, peak level, and combo together. Short practice blocks with rest are more useful than a fatigued record chase."], benchmarks: commonBenchmarks.en, protocols: [{ title: "Calibrate the field", description: "Play one low-pressure round to learn the lane spacing and target size. Keep the pointer near the upper-middle field and notice where new targets enter." }, { title: "Choose the interception point", description: "Click as high in a lane as you can do accurately. Earlier interception leaves more time, but a premature guess creates a miss and breaks the comparison." }, { title: "Track the next lane", description: "Use a soft gaze across the field rather than staring at one falling target. After a click, immediately scan for the next spawn and avoid chasing a target that is already gone." }, { title: "Compare stable sessions", description: "Keep the same device, display, browser, penalty setting, and session length. Record reaction, accuracy, level, and combo so progress is not confused with hardware latency." }], faqs: [{ q: "What is a falling-target reaction game?", a: "It is a browser drill where targets descend through lanes and the player clicks them before they escape. It combines visual detection, moving-target timing, pointer control, and accuracy instead of measuring a single stationary color change." }, { q: "Does this measure my true reaction time?", a: "It measures a browser interaction interval under the drill's rules. Display refresh, frame timing, pointer hardware, browser scheduling, visual processing, and motor movement all affect the result, so compare like-for-like sessions." }, { q: "Why click high in the lane?", a: "A high interception point gives more remaining time before the target reaches the boundary. It is only useful when the click is accurate; clicking early based on a guess increases misses and weakens the measurement." }, { q: "What is the difference from a simple reaction-time test?", a: "A simple test uses one predictable stimulus and one response. This game adds lane selection, moving trajectories, target tracking, spatial choice, and combo management, so it is a more complex reaction task." }, { q: "Can reaction games improve hand-eye coordination?", a: "They can provide repeated practice for aligning visual information with a pointer response. Improvement is task-specific and depends on consistent practice; the drill does not prove a general or clinical change in coordination." }, { q: "Why do my results change between devices?", a: "Refresh rate, display latency, browser load, pointer polling, touch input, frame timing, and screen size can all change when the target becomes visible and when the click is received. Keep the setup fixed for comparisons." }, { q: "How should I practise when I miss many targets?", a: "Prioritise accurate lane selection and a relaxed pointer. Use the upper-middle field, watch for the next spawn with a broad gaze, and raise speed only after several short runs with stable accuracy." }, { q: "Does a faster average always mean better performance?", a: "No. A lower reaction average with many misses can reflect guessing or over-aggressive timing. Read reaction together with accuracy, level, and combo to judge useful performance." }, { q: "How long should a reaction-game session last?", a: "Use five-to-ten-minute blocks with breaks. Stop when attention, accuracy, or hand comfort declines, because fatigue makes later scores difficult to compare with earlier runs." }, { q: "Is this a medical reflex test or a game-rank predictor?", a: "No. It is a free browser training game. It cannot diagnose a health condition or predict an esports rank because both require controlled testing and many factors outside this canvas." }] },

  ko: { locale: "ko_KR", language: "ko-KR", title: "반응 속도 테스트 게임", subtitle: "낙하 표적 반사 신경 훈련", description: "낙하 표적을 클릭하는 무료 반응 속도 테스트 게임입니다. 시각 추적, 포착 타이밍, 정확도와 손·눈 협응을 브라우저에서 연습하세요.", keywords: ["반응 속도 테스트", "반사 신경 테스트", "반응 게임", "순발력 테스트", "낙하 표적 게임", "반응 속도 훈련", "손 눈 협응 게임", "무료 반응 게임"], introTitle: "반응 속도 테스트 게임과 낙하 표적 훈련 가이드", intro: ["움직이는 자극은 단순한 색 변화보다 더 많은 처리를 요구합니다. 레인에 나타난 표적을 발견하고 어디쯤에서 클릭할지 판단한 뒤 포인터를 움직여 표적이 사라지기 전에 맞혀야 합니다. 이 훈련은 시각 탐색, 추적, 타이밍과 손 동작을 한 세션에 묶습니다.", "게임은 표적이 화면에 그려진 시점과 포인터가 닿은 시점 사이를 브라우저 고해상도 시계로 기록합니다. 이 값은 신경계만의 순수한 속도가 아닙니다. 모니터 주사율, 브라우저 프레임, 마우스, 시각 처리와 손 움직임이 모두 영향을 줍니다.", "낙하 표적은 선택 반응도 요구합니다. 어느 레인이 활성화됐는지 보고 빈 곳을 잘못 클릭하지 않으면서 포착 지점을 골라야 합니다. 화면 위쪽 중앙에 포인터를 편하게 두고 넓게 보면 큰 패닉 동작을 줄일 수 있습니다.", "점수는 반복 가능한 훈련 신호로 사용하세요. 같은 모니터, 브라우저, 입력 장치, 감도와 패널티 설정을 유지하면서 정확도, 평균 반응, 최고 레벨과 콤보를 함께 비교합니다. 피로한 기록보다 짧은 블록과 휴식이 더 유용합니다."], benchmarks: commonBenchmarks.ko, protocols: [{ title: "화면 영역 익히기", description: "낮은 부담으로 한 판을 하며 레인 간격과 표적 크기를 익히세요. 포인터를 위쪽 중앙에 두고 표적이 어느 지점에서 나오는지 관찰합니다." }, { title: "포착 지점 고르기", description: "정확하게 할 수 있는 범위에서 레인 위쪽을 클릭하세요. 일찍 맞히면 시간이 남지만 예상으로 누르면 실수가 늘어납니다." }, { title: "다음 레인 추적하기", description: "한 표적만 뚫어지게 보지 말고 화면 전체를 부드럽게 살피세요. 클릭한 뒤 바로 다음 표적을 찾고 이미 사라진 대상을 쫓지 않습니다." }, { title: "조건을 고정해 비교하기", description: "모니터, 브라우저, 입력 장치, 패널티와 세션 길이를 고정합니다. 반응, 정확도, 레벨과 콤보를 함께 기록해 장비 지연을 실력 향상으로 착각하지 마세요." }], faqs: [{ q: "낙하 표적 반응 게임은 무엇인가요?", a: "여러 레인을 따라 내려오는 표적을 바닥에 닿기 전에 클릭하는 브라우저 훈련입니다. 한 번의 색 변화만 재는 대신 시각 발견, 움직임 타이밍, 포인터 조절과 정확도를 함께 요구합니다." }, { q: "이 게임이 실제 반응 시간을 측정하나요?", a: "훈련 규칙 안에서 브라우저 입력 간격을 측정합니다. 모니터 주사율, 프레임, 마우스, 브라우저 처리, 시각 처리와 손 움직임이 포함되므로 같은 조건의 세션끼리 비교하세요." }, { q: "왜 레인 위쪽에서 클릭하나요?", a: "위쪽에서 포착하면 표적이 아래 경계에 닿기 전 남은 시간이 많습니다. 다만 추측으로 너무 일찍 누르면 실수가 늘어 정확도가 떨어집니다." }, { q: "일반 반응 속도 테스트와 무엇이 다른가요?", a: "일반 테스트는 예측 가능한 한 자극과 한 응답을 사용합니다. 이 게임은 레인 선택, 이동 궤적, 표적 추적, 공간 판단과 콤보까지 추가합니다." }, { q: "반응 게임으로 손·눈 협응을 향상할 수 있나요?", a: "시각 정보를 포인터 동작으로 맞추는 반복 연습을 제공할 수 있습니다. 향상은 과제에 특화될 수 있으며 이 게임만으로 일반적 또는 임상적 변화가 증명되지는 않습니다." }, { q: "장비에 따라 점수가 왜 달라지나요?", a: "주사율, 화면 지연, 브라우저 부하, 마우스 폴링, 터치 입력, 프레임 처리와 화면 크기가 표적이 보이고 클릭이 인식되는 시점을 바꿀 수 있습니다." }, { q: "표적을 많이 놓칠 때는 어떻게 연습하나요?", a: "정확한 레인 선택과 편안한 포인터 위치를 먼저 익히세요. 화면 위쪽 중앙에서 넓게 보고 여러 짧은 세션에서 안정된 뒤 속도를 올립니다." }, { q: "평균 반응이 빠르면 항상 더 잘하는 건가요?", a: "아닙니다. 실수가 많으면서 평균만 빠르면 추측하거나 무리하게 누른 결과일 수 있습니다. 정확도, 레벨과 콤보를 함께 읽어야 합니다." }, { q: "한 세션은 얼마나 해야 하나요?", a: "5~10분 블록을 사용하고 쉬세요. 집중력, 정확도 또는 손의 편안함이 떨어지면 피로한 기록을 억지로 갱신하지 않는 편이 좋습니다." }, { q: "의학적 반사 신경 검사나 게임 랭크 예측인가요?", a: "아닙니다. 무료 브라우저 훈련 게임입니다. 건강 상태를 진단하거나 e스포츠 랭크를 예측할 수 없으며, 그런 판단에는 통제된 검사와 다른 요인이 필요합니다." }] },

  ja: { locale: "ja_JP", language: "ja-JP", title: "反応速度テストゲーム", subtitle: "落下ターゲット · 反射神経練習", description: "落下する標的をクリックする無料の反応速度テストゲーム。視覚追跡、捕捉のタイミング、命中率、目と手の協調をブラウザで練習できます。", keywords: ["反応速度テスト", "反射神経テスト", "反応ゲーム", "落下ターゲットゲーム", "反応速度 測定", "動体視力 練習", "目と手の協調", "無料反応ゲーム"], introTitle: "反応速度テストゲームと落下ターゲット練習ガイド", intro: ["動く刺激への反応は、一度の色変化を待つテストより多くの処理を含みます。レーンに現れた標的を見つけ、どこで捕捉するかを判断し、画面下へ抜ける前にポインターを動かしてクリックします。視覚探索、追跡、タイミング、手の操作を一つの課題で練習します。", "ゲームでは標的がフレームに現れた時点からポインターが触れるまでをブラウザの高精度時計で記録します。ただし数値は神経系だけの速さではありません。画面の更新、フレーム処理、入力機器、視覚処理、手の動きが影響します。", "落下ターゲットでは選択反応も必要です。どのレーンが動いているかを見て、空いた場所を誤ってクリックせず、捕捉する位置を選びます。画面上部中央にポインターを置き、広い視野で次の出現を探すと大きな慌てた動きを減らせます。", "同じ画面、ブラウザ、入力機器、感度、ペナルティ、時間でセッションを比べてください。命中率、平均反応、最高レベル、コンボを一緒に記録します。疲れてからの記録更新より、短い練習と休憩の方が比較しやすくなります。"], benchmarks: commonBenchmarks.ja, protocols: [{ title: "フィールドを確認する", description: "まずは落ち着いたラウンドでレーンの間隔と標的の大きさを確認します。ポインターを画面上部中央に置き、出現位置を観察します。" }, { title: "捕捉位置を選ぶ", description: "正確にクリックできる範囲でレーンの上側を狙います。早く捕捉すると時間が残りますが、予測クリックはミスを増やします。" }, { title: "次のレーンを見る", description: "一つの標的だけを凝視せず、画面全体を柔らかく見ます。クリックしたらすぐ次の出現を探し、消えた標的を追い続けません。" }, { title: "同じ条件で比べる", description: "画面、ブラウザ、入力機器、ペナルティ、時間をそろえます。反応、命中率、レベル、コンボを記録して機器の違いと上達を分けます。" }], faqs: [{ q: "落下ターゲットの反応ゲームとは何ですか？", a: "複数のレーンを落ちる標的を、下端に届く前にクリックするブラウザ練習です。色の変化一つではなく、視覚検出、動きのタイミング、ポインター操作、命中率を使います。" }, { q: "本当の反応時間を測れますか？", a: "課題のルール内でブラウザの入力間隔を測ります。画面更新、フレーム、入力機器、ブラウザ、視覚処理、手の動きが入るため、同じ条件で比較してください。" }, { q: "なぜレーンの上側でクリックするのですか？", a: "上側で捕捉すると、標的が下端に着くまでの時間が多く残ります。ただし早すぎる予測クリックはミスを増やし、命中率を下げます。" }, { q: "普通の反応速度テストと何が違いますか？", a: "一般的なテストは予測できる一つの刺激と応答を使います。このゲームはレーン選択、動く軌道、標的追跡、空間判断、コンボを加えた複雑な課題です。" }, { q: "反応ゲームで目と手の協調は鍛えられますか？", a: "視覚情報をポインター操作へ合わせる反復練習にはなります。ただし上達は課題に特化し得るもので、一般的または医学的な改善をこのゲームだけで証明するものではありません。" }, { q: "機器によって結果が変わるのはなぜですか？", a: "画面更新、表示遅延、ブラウザ負荷、マウスのポーリング、タッチ入力、フレーム処理、画面サイズが標的の見える時点とクリック受付を変えます。" }, { q: "ミスが多いときはどう練習しますか？", a: "レーンの選択とポインターの位置を安定させます。画面上部中央から広く見て、短いセッションで命中率が安定してから速度を上げます。" }, { q: "平均反応が速ければ必ず上手いですか？", a: "いいえ。ミスが多いのに平均だけ速い場合は、予測や無理なクリックかもしれません。命中率、レベル、コンボと一緒に見てください。" }, { q: "一回の練習は何分がよいですか？", a: "5〜10分ほどのブロックで練習し、休憩します。集中、命中率、手の快適さが落ちたら、疲労した記録を無理に更新しないでください。" }, { q: "医学的な反射神経検査やゲームのランク予測ですか？", a: "いいえ。無料のブラウザ練習ゲームです。健康状態の診断や競技ランクの予測はできず、その判断には管理された検査と別の要因が必要です。" }] },

  de: { locale: "de_DE", language: "de-DE", title: "Reaktionstest-Spiel", subtitle: "Fallende Ziele · Reflexe trainieren", description: "Kostenloses Reaktionstest-Spiel im Browser mit fallenden Zielen. Trainiere visuelles Tracking, Abfang-Timing, Genauigkeit und Hand-Auge-Koordination.", keywords: ["Reaktionstest", "Reaktionszeit testen", "Reaktionsspiel online", "Reflexe testen", "fallende Ziele Spiel", "Reaktionstraining", "Hand-Auge-Koordination Spiel", "kostenloses Reflexspiel"], introTitle: "Leitfaden für Reaktionstest und fallende Ziele", intro: ["Eine bewegte Reaktionstask ist anspruchsvoller als ein einzelner Farbwechsel. Du erkennst ein Ziel in einer Bahn, schätzt seine Position, bewegst den Pointer und klickst, bevor es unten verschwindet. Der Drill verbindet visuelle Suche, Tracking, Timing und motorische Ausführung.", "Gemessen wird das Intervall zwischen dem Auftauchen des Ziels im Frame und dem Pointerkontakt über die hochauflösende Browserzeit. Dieser Wert ist keine reine Nervensystem-Geschwindigkeit: Bildwiederholung, Frame-Timing, Browser, Eingabegerät, visuelle Verarbeitung und Handbewegung wirken mit.", "Fallende Ziele verlangen außerdem Auswahl. Du musst die aktive Bahn erkennen, den sinnvollen Abfangpunkt wählen und leere Bahnen nicht anklicken. Ein entspannter Pointer nahe der oberen Mitte hilft, neue Ziele ohne große Panikbewegung zu erreichen.", "Nutze den Score als wiederholbares Trainingssignal. Halte Display, Browser, Eingabe, Sensitivität, Strafmodus und Dauer konstant und vergleiche Genauigkeit, mittlere Reaktion, Level und Combo gemeinsam. Kurze Blöcke mit Pausen sind aussagekräftiger als ein müder Rekord."], benchmarks: commonBenchmarks.de, protocols: [{ title: "Feld kalibrieren", description: "Spiele eine ruhige Runde, um Bahnabstände und Zielgröße zu lernen. Halte den Pointer nahe der oberen Mitte und beobachte die Eintrittszone." }, { title: "Abfangpunkt wählen", description: "Klicke so weit oben in der Bahn, wie du sicher triffst. Frühes Abfangen schafft Zeit, aber ein Rateschuss erzeugt einen Fehler." }, { title: "Nächste Bahn verfolgen", description: "Nutze einen weichen Blick über das Feld statt ein Ziel zu fixieren. Suche nach jedem Klick sofort den nächsten Spawn und verfolge kein verschwundenes Ziel." }, { title: "Sessions stabil vergleichen", description: "Halte Gerät, Display, Browser, Strafmodus und Dauer konstant. Notiere Reaktion, Genauigkeit, Level und Combo, damit Hardwarelatenz nicht wie Fortschritt aussieht." }], faqs: [{ q: "Was ist ein Reaktionstest-Spiel mit fallenden Zielen?", a: "Ein Browser-Drill, bei dem Ziele durch Bahnen fallen und vor dem unteren Rand geklickt werden. Er verbindet visuelle Erkennung, Timing, Pointerkontrolle und Genauigkeit statt nur einen stationären Farbwechsel zu messen." }, { q: "Misst der Drill meine echte Reaktionszeit?", a: "Er misst ein Browser-Intervall unter den Spielregeln. Display, Frame-Timing, Eingabegerät, Browser, Wahrnehmung und Motorik beeinflussen den Wert. Vergleiche deshalb gleiche Setups." }, { q: "Warum soll ich weit oben in der Bahn klicken?", a: "Ein hoher Abfangpunkt lässt mehr Zeit bis zur unteren Grenze. Er ist nur dann sinnvoll, wenn der Klick sicher ist; Raten erhöht Fehler und macht den Vergleich schlechter." }, { q: "Was ist anders als bei einem einfachen Reaktionstest?", a: "Ein einfacher Test hat einen vorhersehbaren Reiz und eine Antwort. Dieses Reaktionsspiel ergänzt Bahnauswahl, bewegte Trajektorien, Tracking, räumliche Entscheidung und Combo-Kontrolle." }, { q: "Kann ein Reaktionsspiel die Hand-Auge-Koordination verbessern?", a: "Es bietet wiederholte Übung beim Zuordnen visueller Informationen zu einer Pointerbewegung. Der Transfer ist aufgabenspezifisch; eine allgemeine oder medizinische Verbesserung beweist der Drill nicht." }, { q: "Warum schwankt mein Ergebnis je nach Gerät?", a: "Bildrate, Displaylatenz, Browserlast, Pointer-Polling, Touch-Eingabe, Frame-Timing und Displaygröße verändern Sichtbarkeit und Eingabezeitpunkt. Nutze für Vergleiche dasselbe Gerät." }, { q: "Wie trainiere ich bei vielen Fehlschüssen?", a: "Stabilisiere die Bahnauswahl und eine entspannte Pointerposition. Beobachte das ganze Feld, starte mit dem oberen mittleren Bereich und erhöhe Tempo erst nach stabilen Runs." }, { q: "Ist ein schnellerer Mittelwert immer besser?", a: "Nein. Ein schneller Mittelwert mit vielen Fehlern kann auf Raten oder überhastete Klicks hindeuten. Lies Reaktion gemeinsam mit Genauigkeit, Level und Combo." }, { q: "Wie lange soll eine Session dauern?", a: "Nutze Blöcke von fünf bis zehn Minuten und pausiere. Sinkt die Aufmerksamkeit, Genauigkeit oder Handbequemlichkeit, ist ein weiterer Rekordversuch unter Ermüdung nicht aussagekräftig." }, { q: "Ist das ein medizinischer Reflex-Test oder eine Rangprognose?", a: "Nein. Es ist ein kostenloses Browser-Reaktionsspiel. Es diagnostiziert keine Gesundheit und sagt keinen Esports-Rang voraus, weil dafür kontrollierte Tests und weitere Faktoren nötig sind." }] },

  pt: { locale: "pt_BR", language: "pt-BR", title: "Jogo de Teste de Reflexo", subtitle: "Alvos caindo · Interceptação rápida", description: "Jogo grátis de teste de reflexo no navegador com alvos caindo. Treine acompanhamento visual, timing de interceptação, precisão e coordenação olho-mão.", keywords: ["teste de reflexo", "tempo de reação", "jogo de reflexos", "teste de reação online", "jogo com alvos caindo", "treino de reação", "coordenação olho mão", "jogo de reflexo grátis"], introTitle: "Guia do teste de reflexo com alvos caindo", intro: ["Uma reação a alvos em movimento exige mais do que esperar uma mudança de cor. Você detecta um alvo na faixa, estima onde alcançá-lo, move o ponteiro e clica antes de ele escapar. O treino combina busca visual, acompanhamento, timing e execução motora.", "O jogo registra o intervalo entre o aparecimento do alvo no quadro e o contato do ponteiro usando o relógio de alta resolução do navegador. Esse valor não é uma velocidade pura do sistema nervoso: tela, quadros, navegador, dispositivo de entrada, visão e movimento da mão participam do resultado.", "Os alvos caindo também exigem escolha. É preciso identificar a faixa ativa, escolher o ponto de interceptação e não clicar em uma faixa vazia. Um ponteiro relaxado perto da parte superior central ajuda a reagir sem um movimento brusco.", "Use a pontuação como sinal de treino repetível. Mantenha tela, navegador, entrada, sensibilidade, penalidade e duração constantes e compare precisão, reação média, nível e combo juntos. Blocos curtos com pausas valem mais do que um recorde feito sob cansaço."], benchmarks: commonBenchmarks.pt, protocols: [{ title: "Calibre o campo", description: "Faça uma rodada tranquila para aprender o espaçamento e o tamanho dos alvos. Deixe o ponteiro perto da parte superior central e observe onde surgem." }, { title: "Escolha o ponto de interceptação", description: "Clique o mais alto possível na faixa mantendo a precisão. Interceptar cedo deixa mais tempo, mas chutar o momento aumenta erros." }, { title: "Acompanhe a próxima faixa", description: "Use uma visão ampla do campo em vez de fixar um único alvo. Depois de clicar, procure imediatamente o próximo surgimento e não persiga um alvo que já sumiu." }, { title: "Compare sessões estáveis", description: "Mantenha dispositivo, tela, navegador, penalidade e duração. Registre reação, precisão, nível e combo para separar latência do equipamento de evolução." }], faqs: [{ q: "O que é um jogo de teste de reflexo com alvos caindo?", a: "É um treino no navegador em que os alvos descem pelas faixas e precisam ser clicados antes de escapar. Ele combina detecção visual, timing, controle do ponteiro e precisão." }, { q: "O jogo mede meu tempo de reação real?", a: "Ele mede um intervalo de interação do navegador dentro das regras do jogo. Tela, quadros, entrada, navegador, percepção visual e movimento da mão alteram o resultado; compare condições iguais." }, { q: "Por que clicar no alto da faixa?", a: "Um ponto de interceptação alto deixa mais tempo antes do limite inferior. Só vale quando o clique é preciso; adivinhar cedo demais aumenta erros." }, { q: "Qual é a diferença para um teste simples de reação?", a: "Um teste simples usa um estímulo previsível e uma resposta. Este jogo acrescenta escolha de faixa, trajetória, acompanhamento do alvo, decisão espacial e combo." }, { q: "Jogos de reflexo melhoram coordenação olho-mão?", a: "Eles oferecem repetição para alinhar informação visual e resposta do ponteiro. A melhora pode ser específica da tarefa e não prova uma mudança geral ou clínica." }, { q: "Por que meu resultado muda entre aparelhos?", a: "Frequência da tela, latência, carga do navegador, polling do mouse, toque, quadros e tamanho do display mudam quando o alvo aparece e quando o clique é recebido." }, { q: "Como treinar quando erro muitos alvos?", a: "Estabilize a escolha da faixa e deixe o ponteiro relaxado. Observe o campo todo, use a parte superior central e aumente a velocidade somente após rodadas estáveis." }, { q: "Uma reação média mais rápida é sempre melhor?", a: "Não. Uma média rápida com muitos erros pode indicar chute ou clique apressado. Leia reação junto com precisão, nível e combo." }, { q: "Quanto deve durar uma sessão?", a: "Use blocos de cinco a dez minutos e faça pausas. Se atenção, precisão ou conforto da mão caírem, não persiga um recorde sob fadiga." }, { q: "É um teste médico de reflexo ou prevê rank?", a: "Não. É um jogo gratuito de treino no navegador. Ele não diagnostica saúde nem prevê rank de e-sports, pois isso exige testes controlados e outros fatores." }] },

  es: { locale: "es_ES", language: "es-ES", title: "Juego de Reacción Online", subtitle: "Objetivos que caen · Reflejos rápidos", description: "Juego gratis de test de reacción en navegador con objetivos que caen. Practica seguimiento visual, timing, precisión y coordinación ojo-mano.", keywords: ["test de reacción", "tiempo de reacción", "test de reflejos", "juegos de reflejos", "juego con objetivos que caen", "entrenamiento de reacción", "coordinación ojo mano", "juego de reflejos gratis"], introTitle: "Guía del test de reacción con objetivos que caen", intro: ["Reaccionar a objetivos en movimiento exige más que esperar un cambio de color. Detectas un objetivo en una calle, calculas dónde interceptarlo, mueves el puntero y pulsas antes de que escape. El ejercicio combina búsqueda visual, seguimiento, timing y ejecución motora.", "El juego registra el intervalo entre la aparición del objetivo en un fotograma y el contacto del puntero con el reloj de alta resolución del navegador. Ese valor no es una velocidad pura del sistema nervioso: pantalla, fotogramas, navegador, entrada, visión y movimiento de la mano influyen.", "Los objetivos que caen también exigen elegir. Hay que identificar la calle activa, escoger el punto de intercepción y evitar pulsar en un espacio vacío. Mantener el puntero relajado cerca de la zona superior central ayuda a responder sin un movimiento brusco.", "Usa la puntuación como señal de práctica repetible. Mantén pantalla, navegador, entrada, sensibilidad, penalización y duración constantes y compara precisión, reacción media, nivel y combo juntos. Los bloques cortos con descansos son más útiles que perseguir un récord con fatiga."], benchmarks: commonBenchmarks.es, protocols: [{ title: "Calibra el campo", description: "Haz una ronda tranquila para conocer la separación de las calles y el tamaño de los objetivos. Mantén el puntero cerca de la zona superior central." }, { title: "Elige el punto de intercepción", description: "Pulsa tan arriba como puedas manteniendo la precisión. Interceptar pronto deja más tiempo, pero adivinar aumenta los fallos." }, { title: "Sigue la siguiente calle", description: "Mira el campo de forma amplia en vez de fijarte en un solo objetivo. Después de pulsar, busca de inmediato la siguiente aparición." }, { title: "Compara sesiones estables", description: "Mantén dispositivo, pantalla, navegador, penalización y duración. Registra reacción, precisión, nivel y combo para separar latencia de equipo y progreso." }], faqs: [{ q: "¿Qué es un juego de test de reacción con objetivos que caen?", a: "Es un ejercicio de navegador en el que los objetivos bajan por varias calles y hay que pulsarlos antes de que escapen. Combina detección visual, timing, control del puntero y precisión." }, { q: "¿Mide mi tiempo de reacción real?", a: "Mide un intervalo de interacción del navegador dentro de las reglas del juego. Pantalla, fotogramas, entrada, navegador, percepción y movimiento manual influyen, así que compara condiciones iguales." }, { q: "¿Por qué pulsar arriba de la calle?", a: "Un punto de intercepción alto deja más tiempo antes del límite inferior. Solo sirve si el clic es preciso; anticiparse demasiado provoca fallos." }, { q: "¿En qué se diferencia de un test simple de reacción?", a: "Un test simple usa un estímulo previsible y una respuesta. Este juego añade elección de calle, trayectorias, seguimiento, decisión espacial y control del combo." }, { q: "¿Los juegos de reflejos mejoran la coordinación ojo-mano?", a: "Ofrecen práctica repetida para alinear información visual y respuesta del puntero. La mejora puede ser específica de la tarea y no demuestra un cambio general o clínico." }, { q: "¿Por qué cambia mi resultado según el dispositivo?", a: "Frecuencia de pantalla, latencia, carga del navegador, polling, táctil, fotogramas y tamaño de pantalla cambian cuándo ves el objetivo y cuándo se recibe el clic." }, { q: "¿Cómo practico si fallo muchos objetivos?", a: "Estabiliza la elección de calle y relaja el puntero. Mira todo el campo, empieza en la zona superior central y sube la velocidad solo después de rondas estables." }, { q: "¿Una reacción media más rápida siempre es mejor?", a: "No. Una media rápida con muchos fallos puede indicar que adivinas o pulsas con demasiada agresividad. Lee reacción junto con precisión, nivel y combo." }, { q: "¿Cuánto debe durar una sesión?", a: "Usa bloques de cinco a diez minutos y descansa. Si bajan atención, precisión o comodidad de la mano, no persigas un récord con fatiga." }, { q: "¿Es un test médico de reflejos o predice un rango?", a: "No. Es un juego gratuito de práctica en navegador. No diagnostica salud ni predice un rango de esports, porque eso requiere pruebas controladas y más factores." }] },

  fr: { locale: "fr_FR", language: "fr-FR", title: "Jeu de Test de Réaction", subtitle: "Cibles qui tombent · Réflexes rapides", description: "Jeu gratuit de test de réaction dans le navigateur avec des cibles qui tombent. Travaillez suivi visuel, timing, précision et coordination œil-main.", keywords: ["test de réaction", "temps de réaction", "test de réflexes", "jeu de réflexes", "cibles qui tombent jeu", "entraînement de réaction", "coordination œil main", "jeu de réflexes gratuit"], introTitle: "Guide du test de réaction avec cibles qui tombent", intro: ["Réagir à des cibles en mouvement demande plus que d'attendre un changement de couleur. Repérez une cible dans un couloir, estimez le point d'interception, déplacez le pointeur puis cliquez avant sa sortie. L'exercice associe recherche visuelle, suivi, timing et exécution motrice.", "Le jeu mesure l'intervalle entre l'apparition de la cible dans une image et le contact du pointeur avec l'horloge haute résolution du navigateur. Ce chiffre n'est pas une vitesse pure du système nerveux : écran, images, navigateur, périphérique, vision et mouvement de la main interviennent.", "Les cibles qui tombent ajoutent une décision. Il faut identifier le couloir actif, choisir le point d'interception et éviter une zone vide. Garder le pointeur détendu près de la partie haute centrale aide à répondre sans grand mouvement de panique.", "Utilisez le score comme repère d'entraînement répétable. Gardez écran, navigateur, entrée, sensibilité, pénalité et durée constants, puis comparez précision, réaction moyenne, niveau et combo. Les blocs courts avec pauses valent mieux qu'un record sous fatigue."], benchmarks: commonBenchmarks.fr, protocols: [{ title: "Calibrer le champ", description: "Faites une séance calme pour apprendre l'espacement des couloirs et la taille des cibles. Gardez le pointeur près de la partie haute centrale." }, { title: "Choisir le point d'interception", description: "Cliquez aussi haut que possible tout en restant précis. Intercepter tôt laisse du temps, mais deviner augmente les erreurs." }, { title: "Suivre le couloir suivant", description: "Adoptez un regard large plutôt que de fixer une seule cible. Après chaque clic, cherchez immédiatement la prochaine apparition." }, { title: "Comparer des séances stables", description: "Gardez appareil, écran, navigateur, pénalité et durée constants. Notez réaction, précision, niveau et combo pour distinguer latence et progrès." }], faqs: [{ q: "Qu'est-ce qu'un jeu de test de réaction avec des cibles qui tombent ?", a: "C'est un exercice dans le navigateur où des cibles descendent dans plusieurs couloirs et doivent être cliquées avant de sortir. Il combine détection, timing, contrôle du pointeur et précision." }, { q: "Le jeu mesure-t-il mon vrai temps de réaction ?", a: "Il mesure un intervalle d'interaction du navigateur selon les règles du jeu. Écran, images, entrée, navigateur, perception et mouvement manuel influencent le résultat ; comparez donc des conditions identiques." }, { q: "Pourquoi cliquer en haut du couloir ?", a: "Un point d'interception haut laisse davantage de temps avant la limite basse. Cela ne vaut que si le clic est précis ; anticiper trop tôt augmente les erreurs." }, { q: "Quelle différence avec un test de réaction simple ?", a: "Un test simple utilise un stimulus prévisible et une réponse. Ce jeu ajoute choix du couloir, trajectoire, suivi de cible, décision spatiale et gestion du combo." }, { q: "Les jeux de réflexes améliorent-ils la coordination œil-main ?", a: "Ils proposent une répétition pour relier information visuelle et réponse du pointeur. Le transfert peut rester spécifique à la tâche et ne prouve pas une amélioration générale ou clinique." }, { q: "Pourquoi mon résultat change-t-il selon l'appareil ?", a: "Fréquence d'écran, latence, charge du navigateur, polling, tactile, images et taille d'écran changent le moment où la cible est visible et où le clic est reçu." }, { q: "Comment m'entraîner si je rate beaucoup de cibles ?", a: "Stabilisez le choix du couloir et détendez le pointeur. Regardez l'ensemble du champ, commencez en haut au centre et augmentez la vitesse après des séances régulières." }, { q: "Une réaction moyenne plus rapide est-elle toujours meilleure ?", a: "Non. Une moyenne rapide accompagnée d'erreurs peut indiquer anticipation ou clic précipité. Lisez la réaction avec précision, niveau et combo." }, { q: "Quelle durée pour une séance ?", a: "Utilisez des blocs de cinq à dix minutes et faites une pause. Si attention, précision ou confort de la main diminuent, ne poursuivez pas un record sous fatigue." }, { q: "Est-ce un test médical des réflexes ou une prédiction de classement ?", a: "Non. C'est un jeu gratuit d'entraînement dans le navigateur. Il ne diagnostique pas un état de santé et ne prédit pas un classement esport." }] }
};

const metaDescriptions = Object.fromEntries(Object.entries(content).map(([locale, data]) => [locale, data.description]));

export const REACTION_GAME_I18N = UI;
export function getReactionGameContent(locale = "en") { const key = content[locale] ? locale : "en"; return { ...content[key], description: metaDescriptions[key] }; }
export function getReactionGameUi(locale = "en") { return UI[locale] || UI.en; }

export function buildReactionGameSeo(locale, url, languages) {
  const d = getReactionGameContent(locale);
  const faqSchema = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: d.faqs.slice(0, 10).map(({ q, a }) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })) };
  const breadcrumbSchema = { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: breadcrumbItems(locale, url, 'reaction-speed', d.title, true) };
  const softwareApplicationSchema = { "@context": "https://schema.org", "@type": "SoftwareApplication", name: d.title, alternateName: d.subtitle, applicationCategory: "GameApplication", operatingSystem: "All", offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, description: d.description, url, publisher: { "@type": "Organization", name: "SkillDrills", url: "https://skilldrills.online" }, inLanguage: d.language, dateModified: "2026-09-20", sameAs: ["https://en.wikipedia.org/wiki/Reaction_time", "https://en.wikipedia.org/wiki/Hand%E2%80%93eye_coordination"] };
  const webApplicationSchema = { "@context": "https://schema.org", "@type": "WebApplication", name: d.title, applicationCategory: "GameApplication", operatingSystem: "All", browserRequirements: "HTML5 Canvas and a modern web browser", offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, url, inLanguage: d.language, dateModified: "2026-09-20" };
  const videoGameSchema = { "@context": "https://schema.org", "@type": "VideoGame", name: d.title, url, description: d.description, genre: ["Reaction game", "Reflex training", "Visual tracking"], gamePlatform: ["Web Browser", "Desktop", "Mobile"], applicationCategory: "Game", offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, inLanguage: d.language };
  const howToSchema = { "@context": "https://schema.org", "@type": "HowTo", name: d.introTitle, description: d.description, step: d.protocols.map((step, i) => ({ "@type": "HowToStep", position: i + 1, name: step.title, text: step.description, url: `${url}#step-${i + 1}` })) };
  return { metadata: { title: `${d.title} | SkillDrills`, description: d.description, keywords: d.keywords, openGraph: { ...(locale !== "en" && { images: [{ url: "https://skilldrills.online/opengraph-image", width: 1200, height: 630 }] }), title: `${d.title} | SkillDrills`, description: d.description, type: "article", url, siteName: "SkillDrills", locale: d.locale }, twitter: { ...(locale !== "en" && { images: ["https://skilldrills.online/opengraph-image"] }), card: "summary_large_image", title: `${d.title} | SkillDrills`, description: d.description }, robots: { index: true, follow: true }, alternates: { canonical: url, languages } }, breadcrumbSchema, softwareApplicationSchema, webApplicationSchema, videoGameSchema, faqSchema, howToSchema };
}

export function buildReactionGameGuide(locale, sources) {
  const d = getReactionGameContent(locale);
  const labels = { en: ["Four-phase reaction training protocol", "Frequently asked questions"], ko: ["4단계 반응 훈련 프로토콜", "자주 묻는 질문"], ja: ["4段階の反応練習プロトコル", "よくある質問"], de: ["Reaktionstraining in vier Phasen", "Häufige Fragen"], pt: ["Protocolo de treino de reação em quatro fases", "Perguntas frequentes"], es: ["Protocolo de entrenamiento de reacción en cuatro fases", "Preguntas frecuentes"], fr: ["Protocole d'entraînement de réaction en quatre phases", "Questions fréquentes"] }[locale] || ["Four-phase reaction training protocol", "Frequently asked questions"];
  return { sources, intro: { title: d.introTitle, paragraphs: d.intro }, benchmarks: d.benchmarks, protocols: { title: labels[0], description: d.description, items: d.protocols }, faqs: { title: labels[1], items: d.faqs.map(({ q, a }) => ({ q, a })) } };
}
